#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long countRings(int n, vector<int>& ring, vector<char>& used, const vector<char>& prime) {
    if ((int)ring.size() == n) return prime[ring.back() + ring[0]] ? 1 : 0;
    long long total = 0;
    for (int v = 2; v <= n; v++) {
        if (!used[v] && prime[ring.back() + v]) {
            used[v] = 1;
            ring.push_back(v);
            total += countRings(n, ring, used, prime);
            ring.pop_back();
            used[v] = 0;
        }
    }
    return total;
}

int main() {
    long long n;
    cin >> n;

    vector<char> prime(2 * n + 1, 0);
    for (int x = 2; x <= 2 * n; x++) {
        prime[x] = 1;
        for (int d = 2; d * d <= x; d++) {
            if (x % d == 0) prime[x] = 0;
        }
    }
    vector<int> ring = {1};
    vector<char> used(n + 1, 0);
    cout << countRings((int)n, ring, used, prime) << "\n";

    return 0;
}

